const app=document.getElementById('app');
const TRANSLATION_KEY='english-lab-translations-v1';
let translationCache={};try{translationCache=JSON.parse(localStorage.getItem(TRANSLATION_KEY)||'{}')}catch{}
function saveTranslation(id,text){translationCache[id]=text;try{localStorage.setItem(TRANSLATION_KEY,JSON.stringify(translationCache))}catch{}}
async function translateSentence(q){const sentence=q.q.replace('___',q.answer);if(translationCache[q.id])return translationCache[q.id];const url='https://translate.googleapis.com/translate_a/single?client=gtx&sl=en&tl=zh-TW&dt=t&q='+encodeURIComponent(sentence);const response=await fetch(url);if(!response.ok)throw Error('translation request failed');const data=await response.json();const text=(data[0]||[]).map(x=>x[0]).join('');if(!text)throw Error('empty translation');saveTranslation(q.id,text);return text}
function addTranslation(){const q=session&&byId.get(session.ids[session.index]),el=document.querySelector('.question .explain');if(!q||!el||el.querySelector('.translation'))return;const p=document.createElement('p');p.className='translation';p.innerHTML='<strong>原問題整句翻譯：</strong><span>翻譯載入中…</span>';el.append(p);translateSentence(q).then(text=>{p.querySelector('span').textContent=text}).catch(()=>{p.querySelector('span').textContent='目前無法取得翻譯；請確認手機已連線，稍後可再試。'})}
function addSources(){if(document.querySelector('.cefr-sources'))return;const source=document.createElement('section');source.className='panel cefr-sources';source.innerHTML='<h2>CEFR 備考用分級依據</h2><p>本題庫是原創練習題，依 CEFR Companion Volume、Cambridge A2 Key／B1 Preliminary 詞彙表、English Profile 研究與 Cambridge B2 First 題型方向整理。這些資料用來設計內容，不代表本題庫是官方測驗。</p><p class="sub">A1–A2 著重熟悉生活情境；B1 著重經驗、理由與說明；B2 著重抽象觀點、語氣差異與複合句。練習結果只反映本題庫中的文法與詞彙表現，不等於完整 CEFR 能力證明。</p><p class="sub">首次顯示翻譯時需要網路；翻譯會保存在本機，之後可離線查看已翻譯過的題目。</p><p class="sub"><a href="https://www.coe.int/en/web/common-european-framework-reference-languages/cefr-descriptors" target="_blank" rel="noreferrer">Council of Europe CEFR descriptors</a> · <a href="https://www.cambridgeenglish.org/images/506886-a2-key-2020-vocabulary-list.pdf" target="_blank" rel="noreferrer">Cambridge A2 Key vocabulary list</a> · <a href="https://www.cambridgeenglish.org/Images/506887-b1-preliminary-vocabulary-list.pdf" target="_blank" rel="noreferrer">Cambridge B1 Preliminary vocabulary list</a></p>';app.append(source)}
function addQuestionBasis(){const q=session&&byId.get(session.ids[session.index]),el=document.querySelector('.question');if(!q||!el||el.querySelector('.source-basis'))return;const p=document.createElement('p');p.className='fineprint source-basis';p.textContent='分級參考：'+q.sourceBasis+'。能力焦點：'+q.cefrFocus+'。本題為原創練習題，尚未以正式考生樣本校準。';el.append(p)}
function addResultReference(){const result=document.querySelector('.result'),grid=document.querySelector('.level-grid');if(!result||!grid||result.querySelector('.level-reference'))return;const rows=[...grid.children].map(el=>{const m=el.textContent.match(/(A1|A2|B1|B2)\s+(\d+)\s*\/\s*(\d+)/);return m?{level:m[1],correct:Number(m[2]),total:Number(m[3])}:null}).filter(Boolean);const eligible=rows.filter(x=>x.total>=8),strong=eligible.filter(x=>x.correct/x.total>=.7);const ref=strong.length?strong.at(-1):null;const box=document.createElement('div');box.className='explain level-reference';box.innerHTML=ref?`<strong>本回練習的分級參考：${ref.level}</strong><p>${ref.level} 題組答對 ${ref.correct} / ${ref.total} 題（${Math.round(ref.correct/ref.total*100)}%）。這表示你在本回題目中的表現已達到「可繼續練習 ${ref.level}」的初步參考線；${ref.correct/ref.total>=.8?'表現相對穩定。':'建議再做幾回確認穩定度。'}</p>`:'<strong>本回練習尚無明確分級參考</strong><p>各級題目的答對率尚未達到初步參考線。建議先複習錯題，再分別練習 A1、A2、B1、B2，觀察多回結果。</p>';result.append(box)}
new MutationObserver(()=>{if(document.querySelector('.hero'))addSources();addQuestionBasis();addTranslation();addResultReference()}).observe(app,{childList:true});
const KEY='english-lab-v2';const byId=new Map(bank.map(q=>[q.id,q]));
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const E=escapeHTML;
function blankState(){return {version:2,wrong:[],answered:[],seen:[],attempts:0,correct:0,round:0,history:[],draft:'',active:null}}
function validateState(raw){
 if(!raw||raw.version!==2)throw Error('不支援的紀錄格式');const out=blankState();
 for(const k of ['wrong','answered','seen']){if(!Array.isArray(raw[k])||raw[k].some(id=>!byId.has(id)))throw Error('題目紀錄格式不正確');out[k]=[...new Set(raw[k])]}
 for(const k of ['attempts','correct','round']){if(!Number.isSafeInteger(raw[k])||raw[k]<0)throw Error('統計格式不正確');out[k]=raw[k]}
 if(out.correct>out.attempts)throw Error('正確次數不能超過作答次數');if(typeof raw.draft!=='string'||raw.draft.length>50000)throw Error('草稿格式不正確');out.draft=raw.draft;
 if(!Array.isArray(raw.history))throw Error('歷程格式不正確');out.history=raw.history.slice(-100).map(h=>{if(!h||!Number.isSafeInteger(h.correct)||!Number.isSafeInteger(h.total)||h.total<1||h.total>50||h.correct<0||h.correct>h.total||typeof h.date!=='string'||!Number.isFinite(Date.parse(h.date))||!['practice','exam','review'].includes(h.mode))throw Error('歷程格式不正確');return {date:h.date,correct:h.correct,total:h.total,mode:h.mode}});
 if(raw.active){const a=raw.active;if(!Array.isArray(a.ids)||!a.ids.length||a.ids.length>50||new Set(a.ids).size!==a.ids.length||a.ids.some(id=>!byId.has(id)))throw Error('未完成練習格式不正確');if(!['practice','exam','review'].includes(a.mode)||!Number.isInteger(a.index)||a.index<0||a.index>=a.ids.length||!a.answers||typeof a.answers!=='object'||!a.checked||typeof a.checked!=='object')throw Error('未完成練習格式不正確');const answers={},checked={},options={};for(const id of a.ids){const q=byId.get(id);if(a.answers[id]!==undefined){if(!q.options.includes(a.answers[id]))throw Error('答案不正確');answers[id]=a.answers[id]}if(a.checked[id]===true){if(answers[id]===undefined||a.mode==='exam')throw Error('確認紀錄不正確');checked[id]=true}const opts=a.options?.[id];options[id]=Array.isArray(opts)&&opts.length===4&&new Set(opts).size===4&&opts.every(o=>q.options.includes(o))?opts:[...q.options]}out.active={mode:a.mode,level:LEVELS.includes(a.level)?a.level:'all',kind:['grammar','vocabulary'].includes(a.kind)?a.kind:'all',ids:[...a.ids],index:a.index,answers,checked,options,elapsed:Number.isFinite(a.elapsed)&&a.elapsed>=0?a.elapsed:0}}
 return out;
}
let state=blankState(),storageOK=true,loadMessage='';
try{const raw=localStorage.getItem(KEY);if(raw)state=validateState(JSON.parse(raw));else{const legacy=JSON.parse(localStorage.getItem('english-lab-v1')||'null');if(legacy&&typeof legacy.draft==='string')state.draft=legacy.draft}}catch{storageOK=false;loadMessage='無法讀取這個瀏覽器的紀錄；你仍可練習，並使用匯出備份。'}
let session=null,lastTick=Date.now();
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true}catch{storageOK=false}updateStorageStatus()}
function updateStorageStatus(){const el=document.getElementById('storage-status');if(el){el.textContent=storageOK?'紀錄保留在這台裝置的瀏覽器；不會自動跨裝置同步。':'目前無法自動儲存；請用「匯出紀錄」保留進度。';el.classList.toggle('notice',!storageOK)}}
function checkpoint(){if(session){const now=Date.now();session.elapsed+=Math.max(0,now-lastTick);lastTick=now;state.active=session}save()}
setInterval(()=>{if(session&&document.visibilityState!=='hidden'){checkpoint();const t=document.getElementById('elapsed');if(t)t.textContent=timeLabel(session.elapsed)}},15000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')checkpoint();else lastTick=Date.now()});window.addEventListener('pagehide',checkpoint);
function timeLabel(ms){return Math.floor(ms/60000)+' 分 '+Math.floor(ms/1000)%60+' 秒'}
function navigateTop(){window.scrollTo({top:0,behavior:'instant'})}
function attach(id,fn){const el=document.getElementById(id);if(el)el.onclick=fn}
function notify(msg){const el=document.getElementById('notice');if(el){el.textContent=msg;el.hidden=false}}
function home(){if(session)checkpoint();session=null;const a=state.active;app.innerHTML=`<section class="hero"><div><div class="eyebrow">YOUR PERSONAL ENGLISH PRACTICE</div><h1>隨手練習，<br>一步步<em>更有把握。</em></h1><p>500 題英文練習，從生活情境到工作用語。每回 50 題，平均練到不同難度的文法與單字；做一半也能下次繼續。</p><div class="stats"><div><b>500</b><span>題原創題庫</span></div><div><b>${state.answered.length}</b><span>題已練習</span></div><div><b>${state.history.length}</b><span>回已完成</span></div></div></div><div class="art" aria-hidden="true"><div class="note"><small>ONE DAY. ONE STEP.</small><br><b>Your pace.<br>Your progress.</b><br><span>50 questions, whenever you're ready.</span></div></div></section>${a?`<section class="resume"><div><strong>上次還沒做完，繼續就好。</strong><p>${a.mode==='exam'?'模擬測驗':a.mode==='review'?'錯題複習':'即時練習'} · 已作答 ${Object.keys(a.answers).length} / ${a.ids.length} 題</p></div><button class="btn" id="resume">繼續上次練習 →</button></section>`:''}<div id="notice" class="notice" role="status" ${loadMessage?'':'hidden'}>${E(loadMessage)}</div><h2>今天想怎麼練？</h2><p class="sub">標準混合回合：24 題文法 + 26 題單字，各難度約 12–13 題。</p><div class="filters"><div><label for="level">難度範圍</label><select id="level"><option value="all">平均混合 · A1–B2</option><option value="A1">A1 · 基礎</option><option value="A2">A2 · 初級</option><option value="B1">B1 · 中級</option><option value="B2">B2 · 中高級</option></select></div><div><label for="kind">練習內容</label><select id="kind"><option value="all">文法 + 情境單字</option><option value="vocabulary">只練情境單字</option><option value="grammar">只練文法</option></select></div></div><section class="cards"><article class="card featured"><span class="icon">✦</span><h3>即時練習</h3><p>一回 50 題，每題確認後看中文解析。先理解，再前往下一題。</p><span class="pill pale" style="align-self:flex-start;margin-bottom:18px">優先抽尚未出過的題目</span><button class="btn light" id="practice">開始 50 題練習 ↗</button></article><article class="card"><span class="icon">◷</span><h3>模擬測驗</h3><p>一回 50 題，交卷後一次看成績與解析。中途可暫停，沒有強制限時。</p><span class="pill" style="align-self:flex-start;margin-bottom:18px">練完找出需要加強的方向</span><button class="btn" id="exam">開始 50 題測驗 ↗</button></article><article class="card"><span class="icon">↻</span><h3>錯題再練</h3><p>每回最多 50 題，集中複習還不熟的地方。答對後從待複習清單移出。</p><span class="pill" style="align-self:flex-start;margin-bottom:18px">${state.wrong.length} 題待複習</span><button class="btn ghost" id="review">開啟錯題複習 ↗</button></article></section><section class="writing"><div><h3>Writing corner · 100 字短文</h3><p>練習介紹英文學習經驗與目標，草稿自動保留。</p></div><button class="btn ghost" id="write">練習寫作 →</button></section><section class="panel"><h2>你的學習足跡</h2><div class="level-grid">${LEVELS.map(l=>{const qs=bank.filter(q=>q.level===l);return `<div><strong>${l}</strong><span>${qs.filter(q=>state.answered.includes(q.id)).length} / 125 題已練</span></div>`}).join('')}</div><p class="sub">累計確認 ${state.attempts} 次 · 正確率 ${state.attempts?Math.round(state.correct/state.attempts*100)+'%':'尚無紀錄'} · 已出題 ${state.seen.length} / 500 題</p>${state.history.length?`<div class="history">${state.history.slice(-5).reverse().map(h=>`<div><span>${new Date(h.date).toLocaleDateString('zh-TW')} · ${h.mode==='exam'?'測驗':h.mode==='review'?'錯題':'練習'}</span><strong>${h.correct} / ${h.total}</strong></div>`).join('')}</div>`:''}</section><section class="panel"><h2>只屬於你的練習紀錄</h2><p id="storage-status" class="sub"></p><div class="backup-actions"><button class="btn ghost" id="export">匯出紀錄</button><label class="btn ghost file-btn" for="import">匯入紀錄</label><input id="import" type="file" accept="application/json,.json" hidden><button class="btn ghost" id="phone-help">手機使用說明</button></div><div id="help" hidden class="explain">使用手機時，請固定用同一個瀏覽器開啟。已上線的 HTTPS 網站可加入主畫面，首次完整載入後可離線使用；下載的 HTML 單檔可在支援的瀏覽器中開啟，但不能直接安裝成 App。換裝置前先匯出紀錄，再到新裝置匯入。私密瀏覽或清除網站資料可能使本機紀錄消失。</div></section><p class="fineprint">題庫：A1、A2、B1、B2 各 125 題（各 60 題文法、65 題單字）。難度為練習用的編輯估計，非官方 CEFR 認證。相同字詞可能在不同程度以不同情境出現；260 題單字不等同 260 個不同單字。</p>`;
attach('resume',()=>{session=state.active;lastTick=Date.now();renderQuestion();navigateTop()});
for(const mode of ['practice','exam','review'])attach(mode,()=>start(mode,document.getElementById('level').value,document.getElementById('kind').value));attach('write',writing);attach('export',exportData);attach('phone-help',()=>{const el=document.getElementById('help');el.hidden=!el.hidden});document.getElementById('import').onchange=importData;updateStorageStatus()}
function start(mode,level='all',kind='all'){
 if(state.active&&!confirm('開始新的一回將取代尚未完成的回合；已確認的紀錄會保留。確定開始？'))return;
 let qs=mode==='review'?shuffled(bank.filter(q=>state.wrong.includes(q.id)&&(level==='all'||q.level===level)&&(kind==='all'||q.kind===kind))).slice(0,50):selectRound(bank,state.seen,state.round,level,kind);
 if(!qs.length){notify('目前這個難度與題型沒有待複習的錯題，可以調整篩選條件。');return}
 if(mode!=='review'){state.seen=[...new Set([...state.seen,...qs.map(q=>q.id)])];state.round++}
 const options={};qs.forEach(q=>options[q.id]=shuffled(q.options));session={mode,level,kind,ids:qs.map(q=>q.id),index:0,answers:{},checked:{},options,elapsed:0};state.active=session;lastTick=Date.now();save();renderQuestion();navigateTop();
}
function record(q,a){if(!state.answered.includes(q.id))state.answered.push(q.id);state.attempts++;if(a===q.answer){state.correct++;state.wrong=state.wrong.filter(id=>id!==q.id)}else if(!state.wrong.includes(q.id))state.wrong.push(q.id)}
function renderQuestion(){const s=session,q=byId.get(s.ids[s.index]),a=s.answers[q.id],checked=s.checked[q.id],exam=s.mode==='exam',opts=s.options[q.id];const completed=exam?Object.keys(s.answers).length:Object.keys(s.checked).length;
app.innerHTML=`<section class="session"><div class="topline"><button class="btn ghost" id="pause">← 暫存離開</button><span>${exam?'模擬測驗':s.mode==='review'?'錯題複習':'即時練習'} · ${s.index+1} / ${s.ids.length}</span><span id="elapsed">${timeLabel(s.elapsed)}</span></div><div class="progress" aria-label="已完成 ${completed} 題"><div style="width:${completed/s.ids.length*100}%"></div></div><article class="question"><div class="question-meta"><span class="pill">${q.level} · ${q.kind==='vocabulary'?'單字':'文法'}</span><span>${E(q.topic)}</span></div><h2 lang="en" tabindex="-1">${E(q.q)}</h2>${opts.map((o,i)=>`<button class="option ${a===o?'selected':''} ${checked&&o===q.answer?'correct':''} ${checked&&a===o&&o!==q.answer?'wrong':''}" data-choice="${i}" ${checked?'disabled':''} aria-pressed="${a===o}"><span>${'ABCD'[i]}</span><div lang="en">${E(o)}</div>${checked&&o===q.answer?'<b class="answer-mark" aria-label="正確答案">✓</b>':''}${checked&&a===o&&o!==q.answer?'<b class="answer-mark" aria-label="你的錯誤答案">✕</b>':''}</button>`).join('')}${checked?explanation(q,a):''}<div class="actions"><button class="btn ghost" id="prev" ${s.index===0?'disabled':''}>上一題</button>${!exam&&!checked?`<button class="btn" id="check" ${a===undefined?'disabled':''}>確認答案</button>`:`<button class="btn" id="next">${s.index===s.ids.length-1?'完成並看結果':'下一題 →'}</button>`}</div></article><div class="topline" style="margin-top:20px"><span>已${exam?'作答':'確認'} ${completed} / ${s.ids.length} 題</span><button class="text-btn" id="submit">${exam?'提早交卷':'結算這一回'}</button></div><div class="jump" aria-label="題目導覽">${s.ids.map((id,i)=>`<button class="${(exam?s.answers[id]!==undefined:s.checked[id])?'done':''} ${i===s.index?'current':''}" data-jump="${i}" aria-label="第 ${i+1} 題${(exam?s.answers[id]!==undefined:s.checked[id])?'，已完成':''}" ${i===s.index?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><p class="fineprint">${exam?'交卷前可修改答案。':'確認後才會計入紀錄，已確認答案無法修改。'} 暫存離開後，可在首頁繼續。</p></section>`;
app.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{s.answers[q.id]=opts[Number(b.dataset.choice)];checkpoint();renderQuestion()});app.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{s.index=Number(b.dataset.jump);checkpoint();renderQuestion();navigateTop()});attach('pause',()=>{home();navigateTop()});attach('prev',()=>{s.index--;checkpoint();renderQuestion();navigateTop()});attach('check',()=>{if(s.checked[q.id])return;s.checked[q.id]=true;record(q,s.answers[q.id]);checkpoint();renderQuestion()});attach('next',()=>{if(s.index<s.ids.length-1){s.index++;checkpoint();renderQuestion();navigateTop()}else finish()});attach('submit',finish);
}
function explanation(q,a){return `<div class="explain" role="status"><strong>${a===q.answer?'✓ 答對了':'✕ 再記住這個用法'} · 正確答案：${E(q.answer)}</strong><p>${E(q.explanation)}</p>${q.distractors?`<details><summary>其他選項的意思</summary><p>${q.distractors.map(x=>`${E(x.word)}：${E(x.meaning)}`).join('<br>')}</p></details>`:''}</div>`}
function finish(){const s=session;if(!s)return;const incomplete=s.ids.filter(id=>s.mode==='exam'?s.answers[id]===undefined:!s.checked[id]);if(incomplete.length&&!confirm(`還有 ${incomplete.length} 題未完成。未答或未確認會計為錯誤並加入錯題；確定結算這一回？`))return;checkpoint();for(const id of s.ids){if(s.mode==='exam'||!s.checked[id]){const q=byId.get(id);record(q,s.mode==='exam'?s.answers[id]:undefined);if(s.mode!=='exam')delete s.answers[id]}}
const correct=s.ids.filter(id=>s.answers[id]===byId.get(id).answer).length;state.history.push({date:new Date().toISOString(),correct,total:s.ids.length,mode:s.mode});state.history=state.history.slice(-100);state.active=null;session=null;save();renderResult(s,correct);navigateTop()}
function renderResult(s,correct){const qs=s.ids.map(id=>byId.get(id)),wrong=qs.filter(q=>s.answers[q.id]!==q.answer);app.innerHTML=`<section class="session"><div class="result"><div class="eyebrow">ONE MORE STEP FORWARD</div><h2>今天的練習，留下了。</h2><div class="score">${correct}<small> / ${qs.length}</small></div><p>正確率 ${Math.round(correct/qs.length*100)}% · ${timeLabel(s.elapsed)}</p><button class="btn" id="again">再來 50 題</button> <button class="btn ghost" id="back-home">回練習室</button></div><h2>這回的難度分布</h2><div class="level-grid">${LEVELS.map(l=>{const a=qs.filter(q=>q.level===l);return `<div><strong>${l}</strong><span>${a.filter(q=>s.answers[q.id]===q.answer).length} / ${a.length} 題答對</span></div>`}).join('')}</div><p class="sub">文法 ${qs.filter(q=>q.kind==='grammar').length} 題 · 情境單字 ${qs.filter(q=>q.kind==='vocabulary').length} 題。這是練習成績，不換算正式 CEFR 等級。</p><h2>${wrong.length?'這次值得再練的地方':'全部答對，做得很好。'}</h2>${wrong.map(q=>`<article class="review"><span class="pill">${q.level} · ${q.kind==='vocabulary'?'單字':'文法'}</span><h3 lang="en">${E(q.q)}</h3><p>你的答案：${E(s.answers[q.id]??'未作答／未確認')}</p>${explanation(q,s.answers[q.id])}</article>`).join('')}</section>`;attach('back-home',()=>{home();navigateTop()});attach('again',()=>start(s.mode==='review'?'practice':s.mode,s.level,s.kind))}
function writing(){if(session)checkpoint();session=null;app.innerHTML=`<section class="session"><button class="btn ghost" id="back-home">← 練習室</button><h1 style="font-size:34px">Your English journey.</h1><p>用約 100 個英文字，介紹過去的語言學習經驗與現在的目標。</p><article class="review" style="margin-bottom:22px"><strong>四個方向，幫你開始</strong><p>① 以前在哪裡、怎麼學英文？<br>② 現在透過哪些方式練習？<br>③ 最想改善什麼困難？<br>④ 希望在旅行或工作中達成什麼目標？</p><p lang="en">I started learning English… / These days, I practise… / I find it difficult to… / My goal is to…</p></article><label for="draft">你的英文草稿</label><textarea id="draft" lang="en" placeholder="Write in your own words…">${E(state.draft)}</textarea><div class="topline"><span id="count"></span><span>不提供自動評分</span></div><p id="storage-status" class="sub"></p></section>`;const d=document.getElementById('draft');const update=()=>{state.draft=d.value;document.getElementById('count').textContent=(d.value.trim().match(/\b[\w]+(?:['’-][\w]+)*\b/g)||[]).length+' words';save()};d.oninput=update;update();attach('back-home',home)}
function exportData(){checkpoint();const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='English-Lab-progress-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importData(event){const file=event.target.files?.[0];if(!file)return;try{if(file.size>2000000)throw Error('檔案過大，請選擇匯出的 JSON 紀錄');const imported=validateState(JSON.parse(await file.text()));if(!confirm('匯入會取代這台裝置目前的紀錄。建議先匯出備份；確定匯入？'))return;state=imported;session=null;save();home();notify('紀錄已匯入，可以繼續練習。')}catch(err){notify('匯入失敗：'+err.message)}event.target.value=''}
document.getElementById('home').onclick=e=>{e.preventDefault();home();navigateTop()};
if('serviceWorker' in navigator&&['https:','http:'].includes(location.protocol))navigator.serviceWorker.register('./sw.js').catch(()=>{});
home();
